INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Replikator', 'In this twin-stick roguelite shooter. You play as one of the galactic mercenaries, exploring a mysterious scientific complex and uncover the secret of the REPLIKATOR project. In the role of one of the mercenaries, you will have to fight against hordes of crazed robots and ectoplasmic monsters, while your boss calmly drinks beer in a safe compartment nearby.' FROM games WHERE igdb_id = 145251 ON CONFLICT (game_id, language_code) DO NOTHING;
