INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bean', 'Bean is a single player first person parkour game. To move onto a new level, collect the gold orb and it will teleport you to the next level. Use WASD keys to walk. You can grapple using your burger onto the orange blocks using left click. You can go back to any level after you completed all levels. You are the red bean trying to get to the other 5 beans.' FROM games WHERE igdb_id = 145760 ON CONFLICT (game_id, language_code) DO NOTHING;
