INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stronghold: Warlords', 'The next chapter in Firefly Studios'' real-time strategy series, Stronghold: Warlords is Firefly''s first game to recreate the castle economies of the Far East. In Warlords you take command of Mongol hordes, imperial warriors and samurai clansmen as you lay siege to Japanese castles and fortified Chinese cities. Besiege historical warlords using new gunpowder-fuelled siege weapons, classic units and a completely new way to play Stronghold.' FROM games WHERE igdb_id = 119368 ON CONFLICT (game_id, language_code) DO NOTHING;
