INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cow-catcher', 124594, '2021-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3vxz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aracg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cow Catcher', 'So, you’re a guy in a wingsuit, who really likes to fly in his wingsuit, do crazy stunts, earn money, spend it on more wingsuit flying gadgets, get trophies, that kind of boring stuff. Right? WRONG! Cow Catcher is an unusual wingsuit flight simulator. You become Strange Wingsuit Man, whose goal in life is to fly around, steal random cows and wave his hands like a madman while he’s at it. You might want to think of it as a hobby… STEAL SOME AMAZING COWS You’re job is to kidnap some amazing cows by attaching a rope to them and then transporting them to your pen. Beware though, for the flight is dark and full of… ok, that’s not the story, we beg your pardon. Have you ever handled a cow, high up in the air? No? Well, that’s a shame, but we’ll tell you how it’s done. You have to be very careful not to steer your cow in any of the obstacles awaiting you during your flight. I mean, why would you want to go hitting a cow against…things? That would be crazy. Keep in mind, that typical cows usually wriggle during rope-secured flights. We know that kind of stuff,…' FROM games WHERE igdb_id = 124594 ON CONFLICT (game_id, language_code) DO NOTHING;
