INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chernobylite', 'Chernobylite is a science-fiction survival horror experience, mixing the free exploration of its disturbing world with challenging combat, unique crafting, and non-linear storytelling. Play as a physicist, one of the Chernobyl Power Plant''s ex-employees, and investigate the mysterious disappearance of your beloved. Try to survive and reveal the contamination zone''s twisted secrets. Remember, the military presence is not your only concern.
