INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('madness-beverage', 164298, '2021-07-28', 12, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7hw1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10gv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madness Beverage', 'Madness Beverage is a first-person shooter that takes place in space. It''s a solo campaign, but you''ll never be alone - beware of the demons, they are everywhere and they want to see you dead. You’ll have the chance to visit many unique locations, fight powerful monsters, avoid traps, and fight bosses! Investigate the source of the radio signal in an old castle on Neo Valkyria, discover the secrets of a suspicious-looking laboratory, explore Alien World with its intriguing wildlife and try not to die in flames while on a mission in Lava Cave. There are all sorts of beverages for you to acquire and every single one of them has its own unique power. Protect yourself, slow your enemies, become incredibly powerful and even visit other dimensions, but be careful... the drinks may be toxic! Some of them can make you feel a little fuzzy. Do you often feel nostalgic? Check out the "old-school" mode, which will take you on a journey through the pixelated version of the game! Get a taste of the good, old days! Spend hours tearing up any demon who stands in your way! Watch the blood spurt everywhere and leave the pile of corpses in your wake!' FROM games WHERE igdb_id = 164298 ON CONFLICT (game_id, language_code) DO NOTHING;
