INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'First Class Trouble', 'First Class Trouble is a party game where players must work together and against each other to survive a disaster. The goal is to shut down a deadly A.I. Some players are impostors, secretly playing as human-looking killer robots intent on betraying the other players. First Class Trouble is the perfect marriage of statistics and psychology, of mob rule and democracy, reason and emotion. Add to your wishlist to grab your ticket so we can embark together.' FROM games WHERE igdb_id = 121898 ON CONFLICT (game_id, language_code) DO NOTHING;
