INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons & Dragons: Dark Alliance', 'Set in the Forgotten Realms, the game features real-time combat and dynamic co-op gameplay, and pits the infamous Drizzt Do''Urden and his legendary companions – Catti-brie, Bruenor, and Wulfgar – against some of the most iconic monsters from the world of Dungeons & Dragons. Frost Giants, Beholders, and White Dragons roam the frozen tundra of Icewind Dale in search of the Crystal Shard— and it''s up to the companions to muster the strength to stop them from claiming and using it to destroy their home.' FROM games WHERE igdb_id = 127348 ON CONFLICT (game_id, language_code) DO NOTHING;
