INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teacup', 'Teacup is a narrative adventure game with a focus on exploration and non-linear progression. You play as the titular Teacup, a shy and introverted young frog who loves drinking tea and reading. The day before she is to host a tea party at her house, she realizes she is completely out of tea, and thus must venture into the woods around her to find the herbs she needs to restock her pantry.' FROM games WHERE igdb_id = 142419 ON CONFLICT (game_id, language_code) DO NOTHING;
