INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nectar of the Gods', 'An unquenchable multiplayer real-time strategy game where bugs clash over the sweet nectar of sugary beverages. From Beetle Brigade to Spidey Party, you will artfully master strengths and shortcomings to topple boba shops and coffee bars. The countertop mayhem has begun.' FROM games WHERE igdb_id = 142524 ON CONFLICT (game_id, language_code) DO NOTHING;
