INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faircroft''s Antiques: The Heir of Glen Kinnoch Collector''s Edition', 'Mia Faircroft returns in this thrilling new hidden object adventure! When the untimely demise of one William MacDougal leaves his castle without an heir, Mia is called on to the humble little town of Glen Kinnoch to retrace his past and find his relatives. Uncover long-lost secrets through beautifully rendered hidden object scenes, piece together art and history in engaging minigames, and help the townsfolk find a new future in Faircroft’s Antiques: The Heir of Glen Kinnoch!' FROM games WHERE igdb_id = 147754 ON CONFLICT (game_id, language_code) DO NOTHING;
