INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirate Raid: Caribbean Battle', 'Ahoy me hearties! Ready to hoist the mainsail, batten down the hatches and blaze your way across the Caribbean in search of plunder, glory, and hours of pirate fun? Down your grog and grab your cutlass, it’s all hands on deck in this fast-paced pirate simulator that will really float your boat. Race full-sail across the high seas to do battle with simple merchantmen, naval battleships, and fearsome sea monsters, all while filling your coffers with booty to spend on expanding your tropical island hideaway and upgrading your mighty pirateship in preparation for ever fiercer battles and more dastardly buccaneering further into the game!' FROM games WHERE igdb_id = 188399 ON CONFLICT (game_id, language_code) DO NOTHING;
