INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gem Wizards Tactics', 'Gem Wizards Tactics is a turn-based strategy game with randomly generated maps and weird asymmetrical factions. Designed around endless single player play, Gem Wizards Tactics has three factions each with their own unique abilities which not only combine within factions, but you can also pick up units from other factions and combine them into your army to create new strategies.' FROM games WHERE igdb_id = 142742 ON CONFLICT (game_id, language_code) DO NOTHING;
