INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Car Driving Simulator', 'Car Driving Simulator is a street race game with cool racing cars, city traffic, and racing challenges! Experience extreme speed, do crazy airborne stunts and drift in city traffic on the street’s asphalt - go beyond the speed limit! Car Driving Simulator features racing upgrades and tuning for turbo speed, three race types for a variety of challenge, and lots of rewards for awesome driving. Choose from a wide variety of vehicles, stack your car with racing upgrades and gear to achieve truly turbo speed - progress as a racer and your ride will progress with you!' FROM games WHERE igdb_id = 153835 ON CONFLICT (game_id, language_code) DO NOTHING;
