INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad End Theater', 'Welcome to Bad End Theater! Select your protagonist and explore a variety of terrible fates! The decisions you make in one story will affect the others. you can toggle these behaviors to open up new paths! unfortunately, every path leads to a bad ending... Can you find a way to save this unlucky cast? Playtime: 2-3 hours to see all endings (it''s a puzzle game, so this varies widely).' FROM games WHERE igdb_id = 178264 ON CONFLICT (game_id, language_code) DO NOTHING;
