INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RetroMania Wrestling', 'RetroMania Wrestling is a pick up and play arcade wrestling game with beautiful 2D sprites, incredible backgrounds and fast-paced arcade style game play. With 16 playable characters from legends up to today''s superstars, RetroMania has something for everyone. There are 4 distinct game modes including Story Mode and over 50 possible match variations! Do you have what it takes to step into the RetroMania Wrestling ring?' FROM games WHERE igdb_id = 131604 ON CONFLICT (game_id, language_code) DO NOTHING;
