INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sin-Cay', 'A sci-fi adventure with shooter and puzzle elements. The game follows the adventures of Shin-kai, a half-divine creature animated by ancient magic in an uncharted and mysterious world. The story begins in 1959 in the Soviet Union, in a place called "the mountain of the dead".' FROM games WHERE igdb_id = 162433 ON CONFLICT (game_id, language_code) DO NOTHING;
