INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('minigolf-tour', 165603, '2021-01-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3rk3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11cr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MiniGolf Tour', 'Mini golf, also known as minigolf, mini-putt, or putt-putt, is a sports game in which participants compete by shooting a small ball into special holes with putters. The goal of the game is to cover the allotted distance in the minimum number of strokes. Do you like sports and outdoor activities? Then this golf is perfect for you! Try to complete dozens of challenging levels and show everyone who is the best in minigolf!' FROM games WHERE igdb_id = 165603 ON CONFLICT (game_id, language_code) DO NOTHING;
