INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GTFO', 'GTFO is a 4 player action/horror cooperative game for those looking for a real challenge. Players get to play as a team of scavengers, forced to explore and extract valuable artifacts from a vast underground complex that has been overrun by horrifying monsters. Gather weapons, tools and resources to help you survive - and work to unearth the answers about your past and how to escape.' FROM games WHERE igdb_id = 36646 ON CONFLICT (game_id, language_code) DO NOTHING;
