INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('posledniy-den-v-uryupinske', 368254, '2021-12-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coahu2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vej.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Posledniy Den'' v Uryupinske', 'The Last Day in Uryupinsk is an atmospheric walk through the post-Soviet courtyard to depressive music. Here, as in reality, there is nothing fun. Your only activity is walking. You will slowly walk from side to side and explore this completely ordinary, but still amazing place in its own way. An authentic Russian apartment with wool carpets, an uncomfortable bed and an old TV is waiting for you. After getting out of the apartment, you will find yourself in a classic Russian courtyard, with a destroyed playground, rusty garages and crooked fences.' FROM games WHERE igdb_id = 368254 ON CONFLICT (game_id, language_code) DO NOTHING;
