INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Get Together', 'Get Together is a coop puzzle adventure for two players. Follow the story about a luckless explorer who gets split into two beings. You and a friend take control of these two parts and your goal is as simple as trying to get them back together!INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 144126 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
