INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Fox and the Four Seasons', 'Red Fox has waken up from a very special dream. 42 centuries ago foxes were magical creatures that could regulate the weather. However, this magic came from a crystal which the foxes wore around their neck. The crystal had been lost for such a long time that it became a myth. A story to tell the children.' FROM games WHERE igdb_id = 148529 ON CONFLICT (game_id, language_code) DO NOTHING;
