INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadows of Forbidden Gods', 'A strategy game in which you attempt to bring about the apocalypse, by moving covert agents through a complex fantasy world to accomplish a wide range of schemes, plots and rituals. You start the game by bribing guards and infiltrating minor farming communities and slowly build up your forces until you are bringing about ice ages, eradicating entire nations with plague, summoning volcanoes and commanding city-devouring snake-gods.
