INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Ruins', 'Lost Ruins is a 2D side-scrolling survival action game, where you play as a young girl that has awoken in a strange and foreign place without her memories. With the aid of weapons, spells and tonics, and the guidance of the magical and mysterious Beatrice, you will explore a dark and dangerous world, battle hideous monsters, and topple incredible bosses.' FROM games WHERE igdb_id = 142596 ON CONFLICT (game_id, language_code) DO NOTHING;
