INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eclipse', 'Once upon a time gods sent you here. You’ve slept in a glass sarcophagus for hundrends of years. When people find themselves on the brink of extinction, you’ll have to wake up. Now, the time has come. Get up and save the medieval village from the monsters coming from the abandoned dungeons!' FROM games WHERE igdb_id = 172192 ON CONFLICT (game_id, language_code) DO NOTHING;
