INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anew: The Distant Light', 'Anew: The Distant Light is an open-world, action and adventure game. You are a child with limited resources, waking up on a distant alien moon, twenty light years from Earth. You must carry out a mission of critical importance. Battle, puzzle, and journey through an exotic and dangerous alien world. Seek out game-changing equipment, upgrades, and vehicles to expand your options for combat and exploration.' FROM games WHERE igdb_id = 27214 ON CONFLICT (game_id, language_code) DO NOTHING;
