INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lonley, Lustful, Arrogant, Hateful', 'A unique puzzle adventure with a cryptic story and intriguing drama. Solve puzzles and conquer challenges in a dystopic gameshow. Meet new friends along the way, get to know them and discover their motives. If everyone dies, it''s game over and you''ll have to start from the beginning. Can you keep everyone alive until the end? Are you after glory, love or vengeance?' FROM games WHERE igdb_id = 172726 ON CONFLICT (game_id, language_code) DO NOTHING;
