INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smintheus', '"Hybrid of classical puzzle , adventure and old school RPG genres with some experimental gameplay twists. Smintheus involves linear exploration, fighting against enemies, talking to different characters, having quests and solving puzzles both in classical way and Smintheus way, which is all about crafting gadgets and placing them at right place and right time. Main villain, who''ll appear from time to time, will provide major challenge and boost up game''s stealth mechanic at certain moments."' FROM games WHERE igdb_id = 101171 ON CONFLICT (game_id, language_code) DO NOTHING;
