INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Am Fish', 'I Am Fish is a charming adventure starring four intrepid fish friends, forcibly separated from their home in a pet shop fish tank. Throughout the game, players will join them as they swim, fly, roll, and chomp their way to the open ocean from the far-flung corners of Barnardshire (the smallest county in England) in their bid for freedom and to reunite once again.' FROM games WHERE igdb_id = 125431 ON CONFLICT (game_id, language_code) DO NOTHING;
