INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survive Into Night', 'Stay alive by any means as you face hunger, thirst, limited supplies, and consistent threats from both the living and undead. Sneak and Hide quietly to avoid the undead, or blast your way through the hordes with guns out, making every bullet count. Help other survivors to earn resources for crafting, or let the weak fend for themselves - You''ll face the consequences of your choices.' FROM games WHERE igdb_id = 155504 ON CONFLICT (game_id, language_code) DO NOTHING;
