INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Discoveries of the Deep', 'Join an expedition to the unexplored abyss – a fascinating world of strange creatures, lost vessels, and a wealth of untold secrets. Search for ancient wrecks, underwater trenches, missing airplanes, and even the Titanic. Climb on board your mini-sub and dive as deep as you dare!' FROM games WHERE igdb_id = 69627 ON CONFLICT (game_id, language_code) DO NOTHING;
