INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NoReload Heroes: Enhanced Edition', 'NoReload Heroes Enhanced Edition is a couch co-op twin stick shooter for 1 to 4 that combines the devilishly engaging combat with the shenanigans of having your friends over for game night. Fight the mighty wizbot Mephisto and take on his hordes of henchbots to reclaim the mage’s tower. NoReload Heroes Enhanced Edition sees you fighting your way through 18 levels, 40+ types of enemies, and all with an arsenal of over 150 weapons.' FROM games WHERE igdb_id = 143879 ON CONFLICT (game_id, language_code) DO NOTHING;
