INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Renai Karichaimashita: Koikari - Love For Hire', 'Due to family circumstances, Yuki has only one belief: money will make his little sister happy. And thus, he works part-time jobs late into the night. His plan is to start working full-time after graduation, but his little sister tells him that if he won''t go to university, then she won''t either.' FROM games WHERE igdb_id = 174072 ON CONFLICT (game_id, language_code) DO NOTHING;
