INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aeon-must-die', 114037, '2021-10-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1iqx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arq00.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aeon Must Die', '“Aeon Must Die!” turns the beat-em-up genre on its head introducing breakneck risk-reward gameplay, innovative tactical fighting favoring brains over reflexes, and an RPG alignment system that tracks how you behave as a warrior and changes the challenge and story accordingly. The ruthless, grim but colorful world looks and feels like that ridiculous action-packed anime VHS tape your parents heavily disapproved of. Go on a violent journey with a disgraced symbiotic emperor, a fuel-blooded amnesiac with a hole in his head and a sentient hoverbike.' FROM games WHERE igdb_id = 114037 ON CONFLICT (game_id, language_code) DO NOTHING;
