INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Water Physics Simulation', 'Water Physics Simulation & Sandbox! Build ships and let them sink! Build cars and let them sink! Use bombs and destroy ragdolls. Play with natural disasters or create towns. Do you like liquid simulations? Do you like the flow behavior of water? Do you like bomb explosions? If yes, then you will have much fun with this physics sandbox.' FROM games WHERE igdb_id = 175640 ON CONFLICT (game_id, language_code) DO NOTHING;
