INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fishwitch-halloween', 180971, '2021-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57np.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar199v.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FishWitch Halloween', 'Grab your diving gear and join Beatrice, the guardian of the seven seas, in this enchanted underwater Halloween adventure. Enjoy addictive gameplay as you earn money to decorate a sanctuary with colorful fishes and awesome thematic ornaments. As your sanctuary progresses, you get diamonds with which you can buy cool power-ups to help you beat the levels. Match your way through the wonders of the marine life and explore a bewitching underwater world. Get hooked on FishWitch Halloween.' FROM games WHERE igdb_id = 180971 ON CONFLICT (game_id, language_code) DO NOTHING;
