INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 4: Otome Edition', 'RE4: Otome Edition is a fan-made visual novel parody of Resident Evil 4. Play as Ashley Graham, the president''s kidnapped daughter, as she tries to escape her nightmare while potentially finding some love along the way. Across a 6-7 hour playthrough, diverging pathways, and four unique endings - with plenty of other surprises in between - you''ll never see Resident evil 4 the same way again.' FROM games WHERE igdb_id = 29145 ON CONFLICT (game_id, language_code) DO NOTHING;
