INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Academia: School Simulator', 'Academia : School Simulator is a management game that lets you design, construct, and manage the high school of your dreams! As the school Principal, watch your students as they get bullied, find love, flunk exams, and basically just try to get through the roller-coaster ride that is high school. Will you offer the best teachers and facilities or cheap out and build giant classrooms with a 1:100 student to teacher ratio? It''s all up to you!' FROM games WHERE igdb_id = 55689 ON CONFLICT (game_id, language_code) DO NOTHING;
