INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madness: Project Nexus', 'MADNESS: Project Nexus is a third-person Run n'' Gun / Beat''Em Up filled with arcade-style action and button-mashing brutality. Shoot, stab, bash, chop, and slaughter your way through droves of bad guys in the Story Campaign, or build your perfect killing machine in the neverending onslaught of Arena Mode. Wading through the dismembered remnants of those who fell to your bullets and steel, only one thing crosses your mind: They asked for this. And you''re glad that they did.' FROM games WHERE igdb_id = 58357 ON CONFLICT (game_id, language_code) DO NOTHING;
