INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('combat-mission-cold-war', 144154, '2021-11-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3vou.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar13kg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Combat Mission Cold War', 'Combat Mission Cold War is set in the tipping-point years of a conflict that gripped the world for 45 years. Between 1979-1982, both the NATO and Soviet Warsaw Pact militaries began the shift away from industrialized warfare of the early 20th century and towards the modern digital battlefield of today. Combat Mission Cold War simulates several “what if” conflict scenarios between US and Soviet forces centered on the strategic Fulda Gap and environs in West Germany.
