INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Game is ON', 'The Game is ON is a puzzle game where you have to move things and click around until the situation on the screen matches some well known phrase or idiom from the English language. By solving the puzzles, you get jigsaw pieces. Collect enough pieces to unlock extra levels. You can also get jigsaw pieces by solving the puzzles in least possible moves and by finding pieces hidden in levels. Some are hidden behind other objects or produced after you manipulate buttons or other things on the screen.' FROM games WHERE igdb_id = 147584 ON CONFLICT (game_id, language_code) DO NOTHING;
